#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
using namespace std;

const int INF = 0x3f3f3f3f;
const int MAXN = 20;
const int MAXV = 2 * MAXN * MAXN;

char maze1[MAXN][MAXN], maze2[MAXN][MAXN];
int dist_map[MAXN][MAXN];
int n, t;

int dirX[] = {1, 0, -1, 0};
int dirY[] = {0, 1, 0, -1};

void run_bfs(int startX, int startY) {
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            dist_map[i][j] = INF;
    dist_map[startX][startY] = 0;
    queue<pair<int, int>> q;
    q.push({startX, startY});
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        for (int d = 0; d < 4; ++d) {
            int nx = x + dirX[d], ny = y + dirY[d];
            if (nx >= n || ny >= n || nx < 0 || ny < 0) continue;
            if ('0' <= maze1[nx][ny] && maze1[nx][ny] <= '9' && dist_map[nx][ny] == INF) {
                dist_map[nx][ny] = dist_map[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }
}

vector<int> graph[MAXV];
int capacity[MAXV][MAXV];

void connect(int u, int v, int c) {
    graph[u].push_back(v);
    graph[v].push_back(u);
    capacity[u][v] = c;
    capacity[v][u] = 0;
}

int time_grid[MAXN][MAXN];
bool visited_nodes[MAXV];
int level[MAXV];

bool build_level_graph(int s, int t) {
    memset(level, -1, sizeof(level));
    level[s] = 0;
    queue<int> q;
    q.push(s);
    while (!q.empty() && level[t] == -1) {
        int v = q.front(); q.pop();
        for (auto &nxt : graph[v]) {
            if (!capacity[v][nxt] || level[nxt] != -1) continue;
            level[nxt] = level[v] + 1;
            q.push(nxt);
        }
    }
    return level[t] != -1;
}

void explore_bfs2(int px, int py) {
    memset(time_grid, INF, sizeof(time_grid));
    time_grid[px][py] = 0;
    if ('1' <= maze2[px][py] && maze2[px][py] <= '9')
        connect(n * px + py, n * n + n * px + py, INF);
    queue<pair<int, int>> q;
    q.push({px, py});
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        for (int d = 0; d < 4; ++d) {
            int nx = x + dirX[d], ny = y + dirY[d];
            if (nx >= n || ny >= n || nx < 0 || ny < 0) continue;
            if (time_grid[nx][ny] != INF) continue;
            if (!('0' <= maze1[nx][ny] && maze1[nx][ny] <= '9')) continue;
            if (time_grid[x][y] + 1 <= min(dist_map[nx][ny] - 1, t)) {
                time_grid[nx][ny] = time_grid[x][y] + 1;
                q.push({nx, ny});
            }
            if (time_grid[x][y] + 1 <= min(dist_map[nx][ny], t) && '1' <= maze2[nx][ny] && maze2[nx][ny] <= '9')
                connect(n * px + py, n * n + n * nx + ny, INF);
        }
    }
}

int dfs_flow(int v, int t, int f) {
    if (v == t) return f;
    visited_nodes[v] = true;
    for (auto &nxt : graph[v]) {
        if (!capacity[v][nxt] || visited_nodes[nxt] || level[nxt] != level[v] + 1) continue;
        int pushed = dfs_flow(nxt, t, min(f, capacity[v][nxt]));
        if (pushed) {
            capacity[v][nxt] -= pushed;
            capacity[nxt][v] += pushed;
            return pushed;
        }
    }
    return 0;
}

int max_flow(int s, int t) {
    int total = 0, flow;
    while (build_level_graph(s, t)) {
        memset(visited_nodes, 0, sizeof(visited_nodes));
        while ((flow = dfs_flow(s, t, INF)) > 0) {
            total += flow;
            memset(visited_nodes, 0, sizeof(visited_nodes));
        }
    }
    return total;
}

int main() {
    cin >> n >> t;
    int start_x, start_y;
    int s_node = MAXV - 2, t_node = MAXV - 1;
    for (int a = 0; a < n; ++a) {
        for (int b = 0; b < n; ++b) {
            cin >> maze1[a][b];
            if (maze1[a][b] == 'Z') {
                start_x = a; start_y = b;
            } else if ('1' <= maze1[a][b] && maze1[a][b] <= '9') {
