            }
        }
    }
    run_bfs(start_x, start_y);
    for (int a = 0; a < n; ++a) {
        for (int b = 0; b < n; ++b) {
            cin >> maze2[a][b];
            if ('1' <= maze2[a][b] && maze2[a][b] <= '9') {
                connect(n * n + a * n + b, t_node, maze2[a][b] - '0');
