import java.util.*;
import java.io.*;

public class Main {
    static final int INF = 0x3f3f3f3f;
    static final int MAXN = 20;
    static final int MAXV = 2 * MAXN * MAXN;

    static char[][] maze1 = new char[MAXN][MAXN];
    static char[][] maze2 = new char[MAXN][MAXN];
    static int[][] dist_map = new int[MAXN][MAXN];
    static int n, t;

    static int[] dirX = {1, 0, -1, 0};
    static int[] dirY = {0, 1, 0, -1};

    static List<Integer>[] graph = new ArrayList[MAXV];
    static int[][] capacity = new int[MAXV][MAXV];

    static int[] time_grid = new int[MAXN][MAXN];
    static boolean[] visited_nodes = new boolean[MAXV];
    static int[] level = new int[MAXV];

    static int s_node, t_node;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        t = Integer.parseInt(st.nextToken());

        for (int i = 0; i < MAXV; i++) {
            graph[i] = new ArrayList<>();
        }

        s_node = MAXV - 2;
        t_node = MAXV - 1;

        int start_x = -1, start_y = -1;

        for (int a = 0; a < n; a++) {
            String line = br.readLine();
            for (int b = 0; b < n; b++) {
                maze1[a][b] = line.charAt(b);
                if (maze1[a][b] == 'Z') {
                    start_x = a;
                    start_y = b;
                } else if (maze1[a][b] >= '1' && maze1[a][b] <= '9') {
                    connect(s_node, a * n + b, maze1[a][b] - '0');
                }
            }
        }

        run_bfs(start_x, start_y);

        for (int a = 0; a < n; a++) {
            String line = br.readLine();
            for (int b = 0; b < n; b++) {
                maze2[a][b] = line.charAt(b);
                if (maze2[a][b] >= '1' && maze2[a][b] <= '9') {
                    connect(n * n + a * n + b, t_node, maze2[a][b] - '0');
                }
            }
        }

        for (int a = 0; a < n; a++) {
            for (int b = 0; b < n; b++) {
                if (maze1[a][b] >= '1' && maze1[a][b] <= '9') {
                    explore_bfs2(a, b);
                }
            }
        }

        System.out.println(max_flow(s_node, t_node));
    }

    static void run_bfs(int startX, int startY) {
        for (int i = 0; i < n; ++i)
            Arrays.fill(dist_map[i], INF);
        dist_map[startX][startY] = 0;
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{startX, startY});
        while (!q.isEmpty()) {
            int[] front = q.poll();
            int x = front[0], y = front[1];
            for (int d = 0; d < 4; d++) {
                int nx = x + dirX[d], ny = y + dirY[d];
                if (nx >= n || ny >= n || nx < 0 || ny < 0) continue;
                if ('0' <= maze1[nx][ny] && maze1[nx][ny] <= '9' && dist_map[nx][ny] == INF) {
                    dist_map[nx][ny] = dist_map[x][y] + 1;
                    q.offer(new int[]{nx, ny});
                }
            }
        }
    }

    static boolean build_level_graph(int s, int t) {
        Arrays.fill(level, -1);
        level[s] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(s);
        while (!q.isEmpty() && level[t] == -1) {
            int v = q.poll();
            for (int nxt : graph[v]) {
                if (capacity[v][nxt] == 0 || level[nxt] != -1) continue;
                level[nxt] = level[v] + 1;
                q.offer(nxt);
            }
        }
        return level[t] != -1;
    }

    static int dfs_flow(int v, int t, int f) {
        if (v == t) return f;
        visited_nodes[v] = true;
        for (int nxt : graph[v]) {
            if (capacity[v][nxt] == 0 || visited_nodes[nxt] || level[nxt] != level[v] + 1) continue;
            int pushed = dfs_flow(nxt, t, Math.min(f, capacity[v][nxt]));
            if (pushed > 0) {
                capacity[v][nxt] -= pushed;
                capacity[nxt][v] += pushed;
                return pushed;
            }
        }
        return 0;
    }

    static int max_flow(int s, int t) {
        int total = 0, flow;
        while (build_level_graph(s, t)) {
            Arrays.fill(visited_nodes, false);
            while ((flow = dfs_flow(s, t, INF)) > 0) {
                total += flow;
                Arrays.fill(visited_nodes, false);
            }
        }
        return total;
    }

    static void connect(int u, int v, int c) {
        graph[u].add(v);
        graph[v].add(u);
        capacity[u][v] = c;
        capacity[v][u] = 0;
    }

    static void explore_bfs2(int px, int py) {
        for (int i = 0; i < MAXN; i++) {
            Arrays.fill(time_grid[i], INF);
        }
        time_grid[px][py] = 0;
        if (maze2[px][py] >= '1' && maze2[px][py] <= '9') {
            connect(n * px + py, n * n + n * px + py, INF);
        }
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{px, py});
        while (!q.isEmpty()) {
            int[] front = q.poll();
            int x = front[0], y = front[1];
            for (int d = 0; d < 4; d++) {
                int nx = x + dirX[d], ny = y + dirY[d];
                if (nx >= n || ny >= n || nx < 0 || ny < 0) continue;
                if (time_grid[nx][ny] != INF) continue;
                if (!(maze1[nx][ny] >= '0' && maze1[nx][ny] <= '9')) continue;
                if (time_grid[x][y] + 1 <= Math.min(dist_map[nx][ny] - 1, t)) {
                    time_grid[nx][ny] = time_grid[x][y] + 1;
                    q.offer(new int[]{nx, ny});
                }
                if (time_grid[x][y] + 1 <= Math.min(dist_map[nx][ny], t) && maze2[nx][ny] >= '1' && maze2[nx][ny] <= '9') {
                    connect(n * px + py, n * n + n * nx + ny, INF);
                }
            }
        }
    }
}
